// c2: shooting title is null. c1 recorded that after the focus writer. c1 is kept.
// Table-driven acceptance. Two candidate sessions and a matched control.
// Every navigation key, every edge, the save, and the reopen is asserted.
// A failed comparison, an unresolved control step, or a screenshot error stops the run.
// The chooser header hash is not derived from the help sentence.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_runner_c2.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from './zone_session_k1.mjs';
import { applyStep } from './observe_c1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/accept_runner_c2.mjs om-emu\n');
  process.exit(2);
}
const table = JSON.parse(readFileSync(resolve('work/scripts/accept_table_c2.json'), 'utf8'));
const OUT = resolve('work/out/accept-c2.jsonl');
const lines = [];
let stopped = false;
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify(row));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
const USE_RE = /use\('([^']+)'\)/g;
const controlGot = new Map();

function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
function shaFile(file) {
  const data = readFileSync(file);
  return { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}
function moduleInventory() {
  const seeds = [
    resolve('work/scripts/accept_runner_c2.mjs'),
    resolve('work/scripts/observe_c1.mjs'),
    resolve('work/scripts/zone_session_k1.mjs'),
  ];
  const zoneText = readFileSync(resolve('work/scripts/zone_session_k1.mjs'), 'utf8');
  USE_RE.lastIndex = 0;
  let found;
  while ((found = USE_RE.exec(zoneText))) seeds.push(resolve('om-emu/emu', found[1]));
  const seen = new Map();
  const queue = [...seeds];
  while (queue.length) {
    const file = queue.pop();
    if (seen.has(file) || !existsSync(file)) continue;
    const data = readFileSync(file);
    seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
    const text = data.toString('utf8');
    IMPORT_RE.lastIndex = 0;
    let match;
    while ((match = IMPORT_RE.exec(text))) {
      const next = resolveSpec(file, match[1]);
      if (next && !seen.has(next)) queue.push(next);
    }
  }
  const resources = [
    'inputs/00_0100_50000020.decoded.bin',
    'inputs/02_0106_458c0020.decoded.bin',
    'work/out/overlay-changed-bytes.csv',
    'work/scripts/accept_table_c2.json',
  ].filter((path) => existsSync(resolve(path))).map((path) => ({ path, ...shaFile(resolve(path)) }));
  const modules = [...seen.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([file, rec]) => ({
    path: file.replaceAll('\\', '/'),
    sha256: rec.sha256,
    bytes: rec.bytes,
  }));
  return { modules, resources };
}

function pick(step, role, field) {
  const exp = step.expect;
  if (role === 'control' && exp[field + 'Control'] !== undefined) return exp[field + 'Control'];
  const rb = exp.readback;
  if (rb && role === 'control' && rb[field + 'Control'] !== undefined) return rb[field + 'Control'];
  if (rb && rb[field] !== undefined && field !== 'cells') return rb[field];
  return exp[field];
}

function judgeMenu(step, got, role, previous, controlRow) {
  const exp = step.expect;
  const rb = exp.readback;
  const problems = [];
  if (exp.assertTitle !== false && got.title !== exp.title) problems.push('title');
  if (got.helpText !== exp.helpText) problems.push('helpText');
  if (got.highlight !== exp.highlight) problems.push('highlight');
  if (rb) {
    if (got.screen !== rb.screen) problems.push('screen');
    if (got.profile !== pick(step, role, 'profile')) problems.push('profile');
    if (got.profileCached !== pick(step, role, 'profileCached')) problems.push('profileCached');
    if (!same(got.invariant.k90a1, rb.k90a1)) problems.push('k90a1');
    if (exp.assertFaces !== false) {
      if (got.slotValue !== rb.slotValue) problems.push('slotValue');
      if (got.helpId !== rb.helpId) problems.push('helpId');
    }
    if (exp.assertGlyph !== false && !same(got.glyph, pick(step, role, 'glyph'))) problems.push('glyph');
  }
  if (exp.headerHash && got.headerHash !== exp.headerHash) problems.push('header');
  if (exp.invariant && previous && !same(got.invariant, previous)) problems.push('invariant');
  if (step.controlStep && role === 'candidate') {
    if (!controlRow) problems.push('control-missing');
    else {
      const ui = got.title === controlRow.title
        && got.helpText === controlRow.helpText
        && got.highlight === controlRow.highlight
        && got.screen === controlRow.screen
        && same(got.invariant, controlRow.invariant)
        && (!exp.headerHash || got.headerHash === controlRow.headerHash);
      if (!ui) problems.push('control');
    }
  }
  return problems;
}

function judgeEdge(step, got, role, previous, controlRow) {
  const exp = step.expect;
  const problems = [];
  const target = role === 'control' ? exp.targetControl : exp.target;
  const profile = role === 'control' ? exp.profileControl : exp.profile;
  if (exp.screen !== undefined && got.screen !== exp.screen) problems.push('screen');
  if (target !== undefined && !same(got.target, target)) problems.push('target');
  if (exp.focus !== undefined && got.focus !== exp.focus) problems.push('focus');
  if (exp.subject !== undefined && got.subject !== exp.subject) problems.push('subject');
  if (exp.cells && !same(got.watched, exp.cells)) problems.push('cells');
  if (profile !== undefined && got.profile !== profile) problems.push('profile');
  if (role === 'candidate' && exp.owner !== undefined && got.owner !== exp.owner) problems.push('owner');
  if (exp.invariant && previous && !same(got.invariant, previous)) problems.push('invariant');
  if (step.controlStep && role === 'candidate') {
    if (!controlRow) problems.push('control-missing');
    else if (got.screen !== controlRow.screen || !same(got.watched, controlRow.watched)) problems.push('control');
  }
  return problems;
}

function judge(step, got, role, previous, controlRow) {
  if (step.action === 'edge' || step.action === 'reopen-edge' || step.action === 'reopen-base') {
    return judgeEdge(step, got, role, previous, controlRow);
  }
  if (step.action === 'save') {
    const problems = [];
    if (got.screen !== step.expect.screen) problems.push('screen');
    if (step.expect.invariant && previous && !same(got.invariant, previous)) problems.push('invariant');
    return problems;
  }
  return judgeMenu(step, got, role, previous, controlRow);
}

function record(session, role, step, got, previous) {
  if (step.controlStep && role === 'candidate' && !controlGot.has(step.controlStep)) {
    emit({
      session, id: step.id, key: step.key, action: step.action, pass: false,
      problems: ['control-unresolved'], controlStep: step.controlStep, screenshot: got.screenshot,
    });
    return false;
  }
  const controlRow = role === 'candidate' ? controlGot.get(step.controlStep) : null;
  const problems = judge(step, got, role, previous, controlRow);
  emit({
    session,
    id: step.id,
    key: step.key,
    dir: step.dir,
    action: step.action,
    pass: problems.length === 0,
    problems,
    screenshot: got.screenshot,
    expected: role === 'control' ? {
      target: step.expect.targetControl,
      profile: step.expect.profileControl ?? step.expect.readback?.profileControl ?? step.expect.readback?.profile,
      owner: null,
      title: step.expect.title,
      headerHash: step.expect.headerHash ?? null,
    } : {
      target: step.expect.target,
      profile: step.expect.profile ?? step.expect.readback?.profile,
      owner: step.expect.owner,
      title: step.expect.title,
      headerHash: step.expect.headerHash ?? null,
    },
    actual: {
      title: got.title,
      helpText: got.helpText,
      headerHash: got.headerHash,
      highlight: got.highlight,
      texts: got.texts,
      screen: got.screen,
      profile: got.profile,
      profileCached: got.profileCached,
      slotValue: got.slotValue,
      helpId: got.helpId,
      glyph: got.glyph,
      target: got.target,
      owner: got.owner,
      focus: got.focus,
      subject: got.subject,
      watched: got.watched,
    },
    controlStep: step.controlStep,
  });
  if (role === 'control') controlGot.set(step.id, got);
  return problems.length === 0;
}

function annotate(ctx, got) {
  got.target = ctx.readTarget();
  got.owner = ctx.candidate ? ctx.readOwn()[4] : null;
  got.status = ctx.candidate ? ctx.readOwn()[5] : null;
  got.enabled = ctx.candidate ? ctx.readOwn()[6] : null;
  got.focus = ctx.s.get(289);
  got.subject = ctx.s.get(1712);
  return got;
}

async function prepare(ctx) {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  const api = A(0x50ac4afe);
  const brought = ctx.bringUp();
  ctx.emit('behaviour', {
    step: 'bring-up',
    label: 'EMULATOR-ONLY native bring-up 0x6071181e, 0x608fe1b0, 0x609df7e4, task 105. Role: behaviour.',
    ...brought,
  });
  ctx.s.switch_input('lever', 1);
  ctx.s.camapp.pump();
  ctx.idle(500);
  const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
  ctx.l.call(api, { d0: 289, d1: argument }, null, null, 200000);
  ctx.l.call(api, { d0: 1712, d1: 0 }, null, null, 200000);
  ctx.idle(500);
}

function banks(file) {
  const doc = JSON.parse(readFileSync(resolve(file), 'utf8'));
  return {
    M: Buffer.from(doc.M, 'base64'),
    E: Buffer.from(doc.E, 'base64'),
  };
}

function stepsFor(role, phase) {
  return table.filter((step) => step.phase === phase && (step.who === 'both' || step.who === role));
}

async function session(name, role, phases, nvram) {
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-accept-c2-' + name + '.jsonl',
    tag: 'accept-c2-' + name,
    candidate: role === 'candidate',
    help: true,
    rowLabel: true,
    overlayCsv: role === 'candidate' ? 'work/out/overlay-changed-bytes.csv' : null,
    nvramPath: nvram,
    fatalShots: true,
    explanation: role === 'candidate'
      ? name + ' acceptance on the swapped overlay. Menu zone, 12 edges, zone change, 12 edges, save. Role: behaviour. EMULATOR-ONLY.'
      : name + ' matched control. Same page-27 navigation, cancel instead of the AF-ON commit, same edges, save. No AF-ON overlay.',
    change: role === 'candidate' ? 'profile source swap, already in the overlay' : 'none',
    async drive(ctx) {
      await prepare(ctx);
      let previous = null;
      for (const phase of phases) {
        for (const step of stepsFor(role, phase)) {
          const got = annotate(ctx, await applyStep(ctx, step));
          const ok = record(name, role, step, got, previous);
          previous = got.invariant;
          if (!ok) throw new Error('assertion failed at ' + name + ' ' + step.id);
        }
      }
      if (phases.includes('reopen')) {
        ctx.key('afon', 'up');
        ctx.idle(200);
      }
    },
  });
  if (!result.ok) throw new Error(name + ' failed: ' + result.failed);
  return banks(nvram);
}

const inventory = moduleInventory();
writeFileSync(resolve('work/out/import-inventory-c2.json'), JSON.stringify({
  note: 'SHA-256 taken before the acceptance sessions start.',
  hashed: 'execution',
  ...inventory,
}, null, 2) + '\n');
emit({ record: 'import-inventory', hashed: 'execution', modules: inventory.modules.length, resources: inventory.resources.length });

try {
  const controlNv = 'work/out/nvram-accept-c2-control.json';
  const controlStore = await session('control', 'control', ['menu-a', 'edges-a', 'menu-b', 'edges-b', 'save'], controlNv);
  emit({
    record: 'store-present', session: 'control', pass: controlStore.M.length === 262144 && controlStore.E.length === 196608,
    mBytes: controlStore.M.length, eBytes: controlStore.E.length,
  });
  if (controlStore.M.length !== 262144 || controlStore.E.length !== 196608) throw new Error('control store length');
  const candidateNv = {};
  for (const name of ['c1', 'c2']) {
    const nv = 'work/out/nvram-accept-c2-' + name + '.json';
    candidateNv[name] = nv;
    const store = await session(name, 'candidate', ['menu-a', 'edges-a', 'menu-b', 'edges-b', 'save'], nv);
    const sameM = controlStore.M.equals(store.M);
    const sameE = controlStore.E.equals(store.E);
    emit({ record: 'store', session: name, pass: sameM && sameE, sameM, sameE, mBytes: store.M.length, eBytes: store.E.length });
    if (!sameM || !sameE) throw new Error('store mismatch ' + name);
  }
  await session('reopen-control', 'control', ['reopen'], controlNv);
  for (const name of ['c1', 'c2']) {
    await session('reopen-' + name, 'candidate', ['reopen'], candidateNv[name]);
  }
  emit({ record: 'done', ok: true });
} catch (e) {
  stopped = true;
  emit({ record: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
}
if (stopped) process.exitCode = 1;
